class Solution { private int[] buffer;public int reversePairs(int[] nums){buffer=new int[nums.length];return sort(nums,0,nums.length-1);}private int sort(int[] nums,int left,int right){if(left>=right)return 0;int middle=(left+right)/2;int count=sort(nums,left,middle)+sort(nums,middle+1,right),j=middle+1;for(int i=left;i<=middle;i++){while(j<=right&&(long)nums[i]>2L*nums[j])j++;count+=j-middle-1;}int i=left,k=left;j=middle+1;while(i<=middle||j<=right)buffer[k++]=j>right||(i<=middle&&nums[i]<=nums[j])?nums[i++]:nums[j++];for(k=left;k<=right;k++)nums[k]=buffer[k];return count;} }
